def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Find a solid separator, ignoring uniform background borders.
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != background:
            sep = ("row", r)
            break
    if sep is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and grid[0][c] != background:
                sep = ("col", c)
                break

    if sep is None:
        return [[2 if v != background else 0 for v in row] for row in grid]

    axis, k = sep
    if axis == "row":
        a, b = grid[:k], grid[k + 1:]
        n = min(len(a), len(b))
        return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                 for j in range(w)] for i in range(n)]

    n = min(k, w - k - 1)
    return [[2 if grid[i][j] != 0 and grid[i][w - n + j] != 0 else 0
             for j in range(n)] for i in range(h)]
